import { Button, type ButtonProps } from '@mantine/core';
import { IconFileTypePdf } from '@tabler/icons-react';
import { useState } from 'react';
import { downloadFile, enc } from '../api/client';
import { toast } from '../lib/toast';

/** The viewer's time zone, so dates in the PDF match what the portal shows. */
function timeZone() {
  try {
    return Intl.DateTimeFormat().resolvedOptions().timeZone || '';
  } catch {
    return '';
  }
}

/**
 * Downloads a PDF report generated by the backend.
 * `path` is the API path below /api/v1, e.g. `/orgs/x/runs/y/report.pdf`.
 */
export function ExportPdfButton({
  path,
  fallbackName,
  label = 'Export PDF',
  busyLabel = 'Preparing PDF…',
  ...button
}: {
  path: string;
  fallbackName: string;
  label?: string;
  busyLabel?: string;
  title?: string;
  'aria-label'?: string;
} & Omit<ButtonProps, 'children' | 'loading'>) {
  const [busy, setBusy] = useState(false);

  const run = async () => {
    if (busy) return;
    setBusy(true);
    const tz = timeZone();
    try {
      const name = await downloadFile(tz ? `${path}?tz=${enc(tz)}` : path, fallbackName);
      toast.success('PDF ready', name);
    } catch (e) {
      toast.error('Could not create the PDF', e instanceof Error ? e.message : 'Unknown error');
    } finally {
      setBusy(false);
    }
  };

  return (
    <Button
      variant="default"
      leftSection={<IconFileTypePdf size={16} />}
      {...button}
      onClick={() => void run()}
      disabled={busy || button.disabled}
      aria-busy={busy}
    >
      {busy ? busyLabel : label}
    </Button>
  );
}
